#include <bits/stdc++.h>
using namespace std;
static int ADDT[343][343], NEG[343];
int enc(int x,int y,int z){return x*49+y*7+z;}
array<int,3> decv(int q){return {q/49,(q/7)%7,q%7};}
int inv7(int a){for(int x=1;x<7;x++)if(a*x%7==1)return x;return 0;}
using BS=bitset<343>; using Counts=array<int,343>;
vector<pair<int,int>> makeU(int a){int ia=inv7(a);return {{enc(1,0,0),6},{enc(0,1,0),6},{enc(0,0,1),a},{enc((7-ia)%7,(7-ia)%7,1),7-a}};}
Counts fromU(int a){Counts c{};for(auto [g,m]:makeU(a))c[g]=m;return c;}
int rhoU(int a,int x){if(x==0)return 0;int u=inv7(a),best=99;auto d=decv(x);for(int t=0;t<=7-a;t++){int c1=(d[0]+u*t)%7,c2=(d[1]+u*t)%7,c3=(d[2]-t)%7;if(c3<0)c3+=7;if(c3<=a)best=min(best,c1+c2+c3+t);}return best;}
bool pairDepthOK(int a,const Counts& V,int m){vector<int>e;for(int g=0;g<343;g++)if(V[g])e.push_back(g);function<bool(int,int,int)> rec=[&](int i,int len,int sum){if(i==(int)e.size()){if(len==0||len==m)return true;return len+rhoU(a,NEG[sum])>=m;}int g=e[i],acc=0;for(int t=0;t<=V[g];t++){if(!rec(i+1,len+t,ADDT[sum][acc]))return false;acc=ADDT[acc][g];}return true;};return rec(0,0,0);}
vector<vector<int>> zeroVectorsRange(const Counts& c,int lo,int hi,vector<int>* outElems=nullptr){vector<int> elems;for(int g=0;g<343;g++)if(c[g])elems.push_back(g);if(outElems)*outElems=elems;vector<vector<int>>out;vector<int>cur(elems.size());function<void(int,int,int)>rec=[&](int i,int len,int sum){if(len>hi)return;if(i==(int)elems.size()){if(len>=lo&&sum==0)out.push_back(cur);return;}int g=elems[i],acc=0;for(int t=0;t<=c[g];t++){cur[i]=t;rec(i+1,len+t,ADDT[sum][acc]);acc=ADDT[acc][g];}cur[i]=0;};rec(0,0,0);return out;}
bool zPairExactly2(const Counts& P){vector<int> elems;auto z9=zeroVectorsRange(P,9,9,&elems);vector<int>cap;for(int g:elems)cap.push_back(P[g]);for(int i=0;i<(int)z9.size();i++)for(int j=i;j<(int)z9.size();j++){bool ok=true;for(int k=0;k<(int)cap.size();k++)if(z9[i][k]+z9[j][k]>cap[k]){ok=false;break;}if(ok)return false;}return true;}
string keyCounts(const Counts& c){string s;for(int i=0;i<343;i++)if(c[i])s+=to_string(i)+":"+to_string(c[i])+",";return s;}
struct PairRec{int a;string type;Counts P;};
vector<PairRec> generatePairs(){vector<PairRec>out;set<string>seen;for(int a=1;a<=3;a++){Counts U=fromU(a);set<int>us;for(int g=0;g<343;g++)if(U[g])us.insert(g);int light=enc(0,0,1),u=inv7(a),heavy=enc((7-u)%7,(7-u)%7,1);vector<int>news;for(int g=1;g<343;g++)if(!us.count(g))news.push_back(g);auto tryV=[&](Counts V,string ty){int sum=0,len=0;for(int g=0;g<343;g++)if(V[g]){len+=V[g];int acc=0;for(int q=0;q<V[g];q++)acc=ADDT[acc][g];sum=ADDT[sum][acc];}if(len!=9||sum!=0)return;if(!pairDepthOK(a,V,9))return;Counts P=U;for(int g=0;g<343;g++)P[g]+=V[g];if(!zPairExactly2(P))return;string k=to_string(a)+"|"+keyCounts(V);if(seen.insert(k).second)out.push_back({a,ty,P});};for(int i=0;i<(int)news.size();i++)for(int j=i+1;j<(int)news.size();j++){int x=news[i],y=news[j];for(int side=0;side<2;side++){int s=side?heavy:light;if(U[s]>=6)continue;for(int c=1;c<=6-U[s];c++)for(int r=1;r<=6;r++){int t=9-c-r;if(t<1||t>6)continue;Counts V{};V[s]=c;V[x]=r;V[y]=t;tryV(V,side?"s3H":"s3L");}}if(U[light]<6&&U[heavy]<6)for(int c=1;c<=6-U[light];c++)for(int d=1;d<=6-U[heavy];d++)for(int r=1;r<=6;r++){int t=9-c-d-r;if(t<1||t>6)continue;Counts V{};V[light]=c;V[heavy]=d;V[x]=r;V[y]=t;tryV(V,"s4");}}}return out;}
vector<BS> subsetSums(const Counts& c,int h){vector<BS>dp(h+1);dp[0].set(0);for(int g=0;g<343;g++)if(c[g]){auto old=dp;for(int k=0;k<=h;k++)if(old[k].any()){int cur=0;for(int take=1;take<=min(c[g],h-k);take++){cur=ADDT[cur][g];for(int s=0;s<343;s++)if(old[k][s])dp[k+take].set(ADDT[s][cur]);}}}return dp;}
void enumerateCompanions(const Counts& base,int m,int h,function<void(const vector<int>&)> cb){auto dp=subsetSums(base,h);vector<BS>forb(h+1);for(int j=0;j<=h;j++)for(int k=0;k<=h-j;k++)for(int s=0;s<343;s++)if(dp[k][s])forb[j].set(NEG[s]);vector<int>allowed;for(int x=0;x<343;x++)if(!forb[1][x]&&base[x]<6)allowed.push_back(x);vector<BS>ss(m+1);ss[0].set(0);array<int,343>mult{};vector<int>chosen;function<void(int,int,int)>dfs=[&](int start,int depth,int total){auto validAdd=[&](int x,int d,vector<BS>&news){news.assign(d+2,BS{});for(int k=1;k<=d+1;k++){for(int s=0;s<343;s++)if(ss[k-1][s])news[k].set(ADDT[s][x]);if(k<=h&&(news[k]&forb[k]).any())return false;}return true;};if(depth==m-1){int x=NEG[total];auto it=lower_bound(allowed.begin(),allowed.end(),x);if(it==allowed.end()||*it!=x)return;if(!chosen.empty()&&x<chosen.back())return;if(mult[x]>=6-base[x])return;vector<BS>news;if(!validAdd(x,depth,news))return;auto seq=chosen;seq.push_back(x);cb(seq);return;}for(int pos=start;pos<(int)allowed.size();pos++){int x=allowed[pos];if(mult[x]>=6-base[x])continue;vector<BS>news;if(!validAdd(x,depth,news))continue;vector<BS>old(depth+2);for(int k=1;k<=depth+1;k++){old[k]=ss[k];ss[k]|=news[k];}mult[x]++;chosen.push_back(x);dfs(pos,depth+1,ADDT[total][x]);chosen.pop_back();mult[x]--;for(int k=1;k<=depth+1;k++)ss[k]=old[k];}};dfs(0,0,0);}
bool leqv(const vector<int>& a,const vector<int>& b){for(int i=0;i<(int)a.size();i++)if(a[i]>b[i])return false;return true;}
bool hasPack4(const Counts& c){vector<int>elems;auto z=zeroVectorsRange(c,8,13,&elems);vector<int>cap;for(int g:elems)cap.push_back(c[g]);vector<vector<int>>small;for(auto&v:z){int L=accumulate(v.begin(),v.end(),0);if(L==8||L==9)small.push_back(v);}for(int i=0;i<(int)small.size();i++)for(int j=i;j<(int)small.size();j++){vector<int>rem(cap.size());bool ok=true;for(int k=0;k<(int)cap.size();k++){int q=small[i][k]+small[j][k];if(q>cap[k]){ok=false;break;}rem[k]=cap[k]-q;}if(!ok)continue;int rl=accumulate(rem.begin(),rem.end(),0);for(auto&v:z){int L=accumulate(v.begin(),v.end(),0);if(L<8||L>13||rl-L<8)continue;if(leqv(v,rem))return true;}}return false;}
int main(){for(int i=0;i<343;i++){auto a=decv(i);NEG[i]=enc((7-a[0])%7,(7-a[1])%7,(7-a[2])%7);for(int j=0;j<343;j++){auto b=decv(j);ADDT[i][j]=enc((a[0]+b[0])%7,(a[1]+b[1])%7,(a[2]+b[2])%7);}}auto pairs=generatePairs();map<int,map<string,int>>pc,cc;for(auto&r:pairs)pc[r.a][r.type]++;assert(pairs.size()==26);assert(pc[1]["s3L"]==12);assert(pc[2]["s3L"]==4&&pc[2]["s4"]==6);assert(pc[3]["s3L"]==2&&pc[3]["s3H"]==2);long long comps=0,pack=0;set<string>distinctB;for(auto&r:pairs){enumerateCompanions(r.P,9,7,[&](const vector<int>&w){Counts B=r.P;for(int x:w)B[x]++;comps++;cc[r.a][r.type]++;distinctB.insert(keyCounts(B));if(hasPack4(B))pack++;});}assert(comps==1634&&pack==1634&&distinctB.size()==1634);assert(cc[1]["s3L"]==876);assert(cc[2]["s3L"]==198&&cc[2]["s4"]==142);assert(cc[3]["s3L"]==212&&cc[3]["s3H"]==206);cout<<"{\"status\":\"SUPPORT6_9919_CLOSURE_PRIMARY_GREEN\",\"pair_candidates\":26,\"completions\":"<<comps<<",\"distinct_sequences\":"<<distinctB.size()<<",\"four_pack\":"<<pack<<"}\n";}
